+      return {
+        tableOn: !!window.nameExplainAll,
+        tables: tables.length,
+        nested: nested.length,
+        rows: rows.length,
+        cells,
+        panelText: host ? (host.textContent || "").replace(/\s+/g, " ").trim() : "",
